#!/usr/bin/env python3
"""Summarise `tango-bench` paired `compare` output and publish it into the PR
description.

The section is delimited by HTML comment markers so that re-runs of the
workflow replace the previous results instead of appending a new section.

Expects the output of `<bench-binary> compare <baseline-binary>`: one line per
benchmark like

    Document Build - latin ~250KB   [ 60.1 ms ... 61.8 ms ]    +2.83%*

where a trailing `*` marks a statistically significant difference.
"""

import argparse
import json
import os
import re
import subprocess
import sys

START_MARKER = "<!-- bench-results-start -->"
END_MARKER = "<!-- bench-results-end -->"

ANSI_RE = re.compile(r"\x1b\[[0-9;]*[a-zA-Z]")
RESULT_RE = re.compile(
    r"^(?P<name>.*?)\s*"
    r"\[\s*(?P<base>[^\[\]]*?)\s*\.\.\.\s*(?P<cand>[^\[\]]*?)\s*\]"
    r"\s*(?P<pct>[+-]?\d+(?:\.\d+)?)\s*%"
    r"(?P<sig>\*?)\s*$"
)


class Result:
    def __init__(self, name, baseline, candidate, pct, significant):
        self.name = name
        self.baseline = baseline
        self.candidate = candidate
        self.pct = pct
        self.significant = significant


def parse(text):
    results = []
    for raw_line in text.splitlines():
        line = ANSI_RE.sub("", raw_line).rstrip()
        match = RESULT_RE.match(line)
        if match:
            results.append(
                Result(
                    match["name"].strip(),
                    match["base"].strip(),
                    match["cand"].strip(),
                    float(match["pct"]),
                    match["sig"] == "*",
                )
            )
    return results


def render(results, run_url, base_ref):
    regressions = [r for r in results if r.significant and r.pct > 0]
    improvements = [r for r in results if r.significant and r.pct < 0]

    if not results:
        headline = "No comparable benchmarks were found."
    else:
        headline = (
            f"**{len(regressions)}** significant regressions, "
            f"**{len(improvements)}** significant improvements "
            f"(of {len(results)} benchmarks vs `{base_ref}`)."
        )

    out = [START_MARKER, "## Benchmark results", "", headline, ""]

    if results:
        # Regressions first, then improvements, then noise; largest |Δ| first.
        order = sorted(results, key=lambda r: -r.pct)
        out.append("<details>")
        out.append(f"<summary>Full results ({len(results)} benchmarks)</summary>")
        out.append("")
        out.append("| Benchmark | Baseline | Candidate | Δ |")
        out.append("|---|---:|---:|---:|")
        for r in order:
            delta = f"{r.pct:+.2f}%" + (" **\\***" if r.significant else "")
            out.append(f"| `{r.name}` | {r.baseline} | {r.candidate} | {delta} |")
        out.append("")
        out.append("</details>")
        out.append("")
        out.append(
            "<sub>\\* statistically significant (tango paired test). "
            "Positive Δ means the PR is slower.</sub>"
        )

    if run_url:
        out.append(f"<sub>Generated by the [Benchmarks workflow]({run_url}).</sub>")
    out.append(END_MARKER)
    return "\n".join(out)


def splice(body, section):
    body = body or ""
    start = body.find(START_MARKER)
    end = body.find(END_MARKER)
    if start != -1 and end != -1 and end > start:
        return body[:start] + section + body[end + len(END_MARKER) :]
    if body.strip():
        return body.rstrip() + "\n\n" + section + "\n"
    return section + "\n"


def gh_api(*args, method=None, fields=None):
    cmd = ["gh", "api"]
    if method:
        cmd += ["-X", method]
    cmd += list(args)
    for key, value in (fields or {}).items():
        cmd += ["-f", f"{key}={value}"]
    return subprocess.run(cmd, check=True, capture_output=True, text=True).stdout


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("results_file")
    parser.add_argument("--repo", default=os.environ.get("GITHUB_REPOSITORY"))
    parser.add_argument("--pr", default=os.environ.get("PR_NUMBER"))
    parser.add_argument("--base-ref", default=os.environ.get("BASE_REF", "main"))
    parser.add_argument("--run-url", default=os.environ.get("RUN_URL"))
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()

    with open(args.results_file, encoding="utf-8") as file:
        results = parse(file.read())

    section = render(results, args.run_url, args.base_ref)

    step_summary = os.environ.get("GITHUB_STEP_SUMMARY")
    if step_summary:
        with open(step_summary, "a", encoding="utf-8") as file:
            file.write(section + "\n")

    if args.dry_run or not args.pr:
        print(section)
        return 0

    body = json.loads(gh_api(f"repos/{args.repo}/pulls/{args.pr}")).get("body") or ""
    gh_api(
        f"repos/{args.repo}/pulls/{args.pr}",
        method="PATCH",
        fields={"body": splice(body, section)},
    )
    print(f"Updated the description of PR #{args.pr}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
